ee:message.ee:set-payload:
%dw 2.0
output application/json
var tx = vars.originalTransaction
var txn = if (tx.transaction is Object) tx.transaction else {}
var card = if (tx.card is Object) tx.card else {}
var customer = if (tx.customer is Object) tx.customer else {}
var merchant = if (tx.merchant is Object) tx.merchant else {}
var device = if (tx.device is Object) tx.device else {}
---
{
	queueName: vars.targetQueue,
	messagePriority: vars.messagePriority,
	event: {
		eventId: tx.eventId,
		transactionId: txn.transactionId,
		cardToken: card.cardToken,
		maskedCardNumber: card.maskedCardNumber,
		amount: txn.amount,
		currency: txn.currency,
		customerId: customer.customerId,
		merchantId: merchant.merchantId,
		merchantCountry: merchant.merchantCountry,
		geoCountry: device.geoCountry,
		riskScore: tx.riskScore,
		riskBand: vars.riskBand,
		ruleHits: tx.ruleHits,
		correlationId: tx.correlationId
	}
}

%dw 2.0
output application/json
var cid = vars.originalTransaction.correlationId
---
{
	status: "REJECTED",
	(correlationId: cid) if (cid is String),
	error: {
		code: "INVALID_INPUT",
		message: "The transaction failed validation and was not published.",
		details: vars.validationErrors default []
	}
}

%dw 2.0
output application/json
---
{
	status: "FAILED",
	correlationId: vars.correlationId,
	routing: { riskBand: vars.riskBand, queue: vars.targetQueue, published: false, deadLettered: false },
	error: {
		code: "DLQ_PUBLISH_FAILED",
		message: "Primary publish failed after retries and the transaction could not be dead-lettered. It was NOT delivered to any queue; the caller must retry."
	}
}

%dw 2.0
output application/json
---
{
	status: "FAILED",
	correlationId: vars.correlationId,
	error: { code: "VELOCITY_BUSY", message: "Velocity state for this card is busy. Nothing was published; please retry." }
}

%dw 2.0
output application/json
---
{
	status: "FAILED",
	error: { code: "INTERNAL_ERROR", message: "The transaction could not be processed. Nothing was confirmed as published." }
}

ee:variables.ee:set-variable:
%dw 2.0
import try from dw::Runtime
output application/java
var useEventTs = (p('velocity.useEventTimestamp') as Boolean)
var windowSeconds = (p('velocity.windowSeconds') as Number)
var windowMs = windowSeconds * 1000
var threshold = (p('velocity.threshold') as Number)
var maxTs = (p('velocity.maxTimestamps') as Number)
var cmp = upper(p('velocity.comparison'))
var ref = (vars.referenceMillis as Number)
var cutoff = ref - windowMs
var parsed = try(() -> read(vars.storedVelocityState as String, "application/json"))
var stored = if (parsed.success and (parsed.result.timestamps is Array)) (parsed.result.timestamps filter ($ is Number)) else []
var active = stored filter ($ >= cutoff)
var merged = (active ++ [ref]) orderBy $
var capped = if (sizeOf(merged) > maxTs) merged[(sizeOf(merged) - maxTs) to -1] else merged
var count = sizeOf(capped)
var exceeded = if (cmp == "GTE") (count >= threshold) else (count > threshold)
---
{
	timestamps: capped,
	velocity: {
		count: count,
		windowType: "SLIDING",
		windowSeconds: windowSeconds,
		windowStart: ((cutoff as DateTime {unit: "milliseconds"}) as String),
		windowEnd: ((ref as DateTime {unit: "milliseconds"}) as String),
		expiredRemoved: sizeOf(stored) - sizeOf(active),
		threshold: threshold,
		comparison: if (cmp == "GTE") "GTE" else "GT",
		thresholdExceeded: exceeded,
		timestampSource: if (useEventTs) "EVENT_TIMESTAMP" else "SERVER_TIME"
	}
}
